Given a singly linked list, we have to check whether it is a palindrome or not.Examples:Input: Output: trueExplanation: It forms the same sequence when read from front to back and from back to front.Input:  Output: falseExplanation: Not and PalindromeTry It YourselfTable of Content[Approach - 1] Using Stack - O(n) Time and O(n) Space[Approach - 2] Using Recursion - O(n) Time and O(n) Space[Expected Approach] Using Iterative Method - O(n) Time and O(1) Space[Approach - 1] Using Stack - O(n) Time and O(n) SpaceThe idea is to use stack and start traversing from the head node. Push all the node and then start comparing from the head node with top value of stack.Steps to solve the problem:Push all the node's data into the stack.Again traverse from the head node.Compare the popped node's data with the current node's data.If both are not equal ,return false .If all elements match ,return true.Below is the implementation of the above approach : 
            C++

    #include <iostream>
#include <stack>
using namespace std;

class Node {
public:
    int data;
    Node* next;
    Node(int d) { 
        data = d; 
        next = nullptr;
    }
};

// Function to check if the linked list 
// is palindrome or not
bool isPalindrome(Node* head) {
    Node* currNode = head;

    // Declare a stack
    stack<int> s;

    // Push all elements of the list to the stack
    while (currNode != nullptr) {
        s.push(currNode->data);
        currNode = currNode->next;
    }

    // Iterate in the list again and check by
  	// popping from the stack
    while (head != nullptr) {

        // Get the topmost element
        int c = s.top();
        s.pop();

        // Check if data is not same as popped element
        if (head->data != c) {
            return false;
        }

        // Move ahead
        head = head->next;
    }

    return true;
}

int main() {

    // Linked list : 1->2->3->2->1
    Node* head = new Node(1);
    head->next = new Node(2);
    head->next->next = new Node(3);
    head->next->next->next = new Node(2);
    head->next->next->next->next = new Node(1);

    bool result = isPalindrome(head);

    if (result)
        cout << "true\n";
    else
        cout << "false\n";

    return 0;
}


